                                        Some(guard),
                                        Some(budget.clone()),
                                    );
                                Ok(ClientBidiStreamHandle::new_with_budget_and_slot(
                                    read_rx,
                                    write_tx,
                                    stop_tx,
                                    Some(budget),
                                    write_err_slot,
                                ))
