	queuedBytesGlobal: number;
	backpressureWaitCount: number;
	backpressureTimeoutCount: number;

	rateLimitedCount: number;
	limitExceededCount: number;

	/** Handshake latency (accept start to completion). P99 target &lt;300ms. */
