	packetsLost?: number;
	bytesReceived?: number;
	packetsReceived?: number;
	smoothedRtt?: number;
	rttVariation?: number;
	minRtt?: number;
	estimatedSendRate?: number | null;
	atSendCapacity?: boolean;
};

