import { getCertHashBase64 } from "../cert-hash.js";

function wtConnectScript(hashBase64: string): string {
    return `
        const opts = {};
        const h = "${hashBase64}";
        if (h) {
            const bin = Uint8Array.from(atob(h), (c) => c.charCodeAt(0));
            opts.serverCertificateHashes = [{ algorithm: "sha-256", value: bin }];
