		it("compliant connects within refill window after abusive burst (tokens refill, no permanent starvation)", async () => {
			const port = nextPort(14900, 200);
			const burst = 2;
			const server = trackedCreateServer({
				port,
				tls: { certPem: "", keyPem: "" },
