			})();

			await Promise.all([compliantPromise, abusivePromise]);

			expect(compliantConnected).toBe(true);

			const m = server.metricsSnapshot();
			expect(m.rateLimitedCount).toBeGreaterThanOrEqual(0);

			await server.close();
		}, 20000);
	});
